import {reservationStatus,type CancellationDisposition} from '@/lib/reservation-status';
import {reportMoney,type ReportCell} from '@/lib/report-export';
type Property={id:string;name:string;time_zone:string};
type Common={property:Property;currency:'USD';payment_recording:'external_only';rows_truncated:false;definitions:Record<string,string>};
export const activityKinds:Record<string,string>={charge:'Additional charge',charge_reversal:'Charge reversal',external_payment:'External payment record',external_refund:'External refund record',payment_correction:'Payment record reduction'};
export const activityMeasures=[['additional_minor','Additional charges'],['reversed_minor','Charge reversals'],['external_payments_minor','External payment records'],['external_refunds_minor','External refund records'],['corrected_payments_minor','Payment record reductions'],['charges_effect_minor','Net charge effect'],['recorded_paid_effect_minor','Net recorded-payment effect'],['balance_effect_minor','Net balance effect']] as const;
export const balanceMeasures=[['charges_minor','Known charges'],['recorded_paid_minor','Known recorded payments, net'],['original_balance_minor','Known original balance'],['routed_charge_minor','Transferred charges'],['balance_minor','Known guest balance'],['positive_balances_minor','Known positive balances'],['credit_balances_minor','Known credit balances (signed)']] as const;
export type ActivityRow=CancellationDisposition&{id:string;request_id:string;reservation_id:string;source:string;source_booking_id:string;status:string;kind:string;amount_minor:number;reference:string;reason:string;target_entry_id:string|null;actor_id:string;created_at:string;local_date:string;charges_effect_minor:number;recorded_paid_effect_minor:number;balance_effect_minor:number};
export type ActivityReport=Common&{period:{start:string;end:string;end_exclusive:true;start_at:string;end_at:string};generated_at:string;rows:ActivityRow[];totals:Record<typeof activityMeasures[number][0],number>&{entry_count:number;complete:true}};
type RowTotals={original_balance_minor:number;routed_charge_minor:number;additional_minor:number;reversed_minor:number;charges_minor:number;external_payments_minor:number;external_refunds_minor:number;corrected_payments_minor:number;recorded_paid_minor:number;balance_minor:number};
export type BalanceRow=CancellationDisposition&{reservation_id:string;source:string;source_booking_id:string;status:string;arrival:string|null;departure:string|null;available:boolean;reason:string|null;opening_mode:'frozen'|'reservation_preview'|'unavailable';reservation_amounts_changed:boolean;pricing_reconciliation_required:boolean;current_reservation_total_minor:number|null;opening:{accommodation_minor:number;taxes_minor:number;hotel_fees_minor:number;ota_fees_minor:number;total_minor:number;opened_at:string|null}|null;totals:RowTotals|null};
export type BalanceReport=Common&{schema_version:2;tenant_id:string;property_id:string;as_of:string;business_date:string;rows:BalanceRow[];totals:Record<typeof balanceMeasures[number][0],number>&{reservation_count:number;available_count:number;unavailable_count:number;positive_balance_count:number;credit_balance_count:number;zero_balance_count:number;changed_reservation_count:number;pricing_review_count:number;complete:boolean}};
export const activityHeaders=['Recorded at','Local recording date','Entry reference','Reservation','Source','Source booking reference','Current status','Entry type','Amount USD','Charge effect USD','Recorded-payment effect USD','Balance effect USD','Actor','Document reference','Reason','Applied against entry'];
export const balanceHeaders=['Reservation','Source','Source booking reference','Current status','Arrival','Departure','Amount basis','Availability reason','Opening accommodation USD','Opening tax USD','Opening property fees USD','Opening OTA fees USD','Opening total USD','Opening frozen at','Current reservation total USD','Additional charges USD','Charge reversals USD','Known charges USD','External payment records USD','External refund records USD','Payment record reductions USD','Net recorded paid USD','Original balance USD','Transferred charges USD','Guest balance USD','Reservation differs from opening','Pricing review required'];
export const balanceBasis=(mode:BalanceRow['opening_mode'])=>({frozen:'Frozen folio opening',reservation_preview:'Current reservation preview',unavailable:'Unknown charge amounts'})[mode];
const money=(value:number|null|undefined)=>value==null?'Unknown':reportMoney(value);
export {reportUsd as folioMoney} from '@/lib/report-export';
export function activityRows(report:ActivityReport):ReportCell[][]{return report.rows.map(r=>[r.created_at,r.local_date,r.id,r.reservation_id,r.source,r.source_booking_id,reservationStatus(r),activityKinds[r.kind]??r.kind,...[r.amount_minor,r.charges_effect_minor,r.recorded_paid_effect_minor,r.balance_effect_minor].map(reportMoney),r.actor_id,r.reference,r.reason,r.target_entry_id])}
export function balanceRows(report:BalanceReport):ReportCell[][]{return report.rows.map(r=>[r.reservation_id,r.source,r.source_booking_id,reservationStatus(r),r.arrival,r.departure,balanceBasis(r.opening_mode),r.reason,...[r.opening?.accommodation_minor,r.opening?.taxes_minor,r.opening?.hotel_fees_minor,r.opening?.ota_fees_minor,r.opening?.total_minor].map(money),r.opening?.opened_at,money(r.current_reservation_total_minor),...[r.totals?.additional_minor,r.totals?.reversed_minor,r.totals?.charges_minor,r.totals?.external_payments_minor,r.totals?.external_refunds_minor,r.totals?.corrected_payments_minor,r.totals?.recorded_paid_minor,r.totals?.original_balance_minor,r.totals?.routed_charge_minor,r.totals?.balance_minor].map(money),r.reservation_amounts_changed?'Yes':'No',r.pricing_reconciliation_required?'Yes':'No'])}

// Verify scoped balance amounts before showing totals or enabling report export.
export function validateBillingBalanceReport(value:unknown,tenant:string,property:string):asserts value is BalanceReport{
 const fail=()=>{throw Error('The complete guest balance report could not be verified. Refresh before exporting.')};
 if(!value||typeof value!=='object')return fail();const r=value as BalanceReport;
 if(r.schema_version!==2||r.tenant_id!==tenant||r.property_id!==property||r.property?.id!==property||r.currency!=='USD'||r.rows_truncated!==false||!Array.isArray(r.rows)||!r.totals)return fail();
 const keys=['charges_minor','recorded_paid_minor','original_balance_minor','routed_charge_minor','balance_minor','positive_balances_minor','credit_balances_minor'] as const;
 const sums=Object.fromEntries(keys.map(k=>[k,0n])) as Record<typeof keys[number],bigint>;let available=0,positive=0,credit=0,zero=0;const seen=new Set<string>();
 for(const row of r.rows){
  if(!row||typeof row.reservation_id!=='string'||seen.has(row.reservation_id)||typeof row.available!=='boolean')return fail();seen.add(row.reservation_id);
  if(!row.available){if(row.totals!==null||row.opening!==null)return fail();continue}
  available++;const t=row.totals;if(!t||Object.values(t).some(v=>!Number.isSafeInteger(v)))return fail();
  for(const k of keys.slice(0,5))if(!Number.isSafeInteger(t[k as keyof RowTotals]))return fail();
  if(t.routed_charge_minor<0||BigInt(t.charges_minor)-BigInt(t.recorded_paid_minor)!==BigInt(t.original_balance_minor)||BigInt(t.original_balance_minor)-BigInt(t.routed_charge_minor)!==BigInt(t.balance_minor))return fail();
  for(const k of keys.slice(0,5))sums[k]+=BigInt(t[k as keyof RowTotals]);
  if(t.balance_minor>0){positive++;sums.positive_balances_minor+=BigInt(t.balance_minor)}else if(t.balance_minor<0){credit++;sums.credit_balances_minor+=BigInt(t.balance_minor)}else zero++;
 }
 for(const k of keys)if(!Number.isSafeInteger(r.totals[k])||BigInt(r.totals[k])!==sums[k])return fail();
 if(r.totals.reservation_count!==r.rows.length||r.totals.available_count!==available||r.totals.unavailable_count!==r.rows.length-available||r.totals.positive_balance_count!==positive||r.totals.credit_balance_count!==credit||r.totals.zero_balance_count!==zero||r.totals.complete!==(available===r.rows.length))return fail();
}
